INSERT INTO `artists` VALUES (17,'va9nqk4w8dsixc','Adele Laurie','Adele Laurie Blue Adkins MBE is an English singer-songwriter. After graduating from the BRIT School in 2006, Adele signed a recording contract with XL Recordings. In 2007, she received the Brit Awards Critics Choice award and won the BBC Sound of 2008 poll.','/upload/images/channels/artists/1577961536493_l35lzd_AdeleLaurie_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(18,'va9wdk4wiwdorc','Beyonce Giselle','Beyoncé Giselle Knowles-Carter is an American singer, songwriter, record producer, and actress. Born and raised in Houston, Texas, Beyoncé performed in various singing and dancing competitions as a child.','/upload/images/channels/artists/1577961526811_0fsrks_beyonce_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(19,'va9wdk4wix66pc','Britney Spears','Britney Jean Spears is an American singer, songwriter, dancer, and actress. Born in McComb, Mississippi and raised in Kentwood, Louisiana, she appeared in stage productions and television series, before signing with Jive Records in 1997. Spears first two studio albums, ...Baby One More Time and Oops!','/upload/images/channels/artists/1577961518999_hbdjkq_BritneySpears_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(20,'va9wdk4wixo71c','Chris Brown','Christopher Maurice Brown is an American singer, songwriter and dancer. Born in Tappahannock, Virginia, he was involved in his church choir and several local talent shows from a young age.','/upload/images/channels/artists/1577961512448_vg6jdk_ChrisBrown_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(21,'va9wdk4wiyk5cc','Aubrey Drake Graham','Aubrey Drake Graham is a Canadian rapper, singer, songwriter, producer, actor, and businessman. Drake initially gained recognition as an actor on the teen drama television series Degrassi.','/upload/images/channels/artists/1577961505179_fhp3fl_Drake_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(22,'va9wdk4wiz3ywc','Eminem','Marshall Bruce Mathers III, known professionally as Eminem, is an American rapper, songwriter, record producer, record executive, film producer, and actor. He is consistently cited as one of the greatest and most influential rappers of all time.','/upload/images/channels/artists/1577961494637_rhe2zm_Eminem_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(23,'va9wdk4wkunc4c','Halle Berry','Halle Maria Berry is an American actress. Berry won the Academy Award for Best Actress for her performance in the romantic drama film Monsters Ball, becoming the only woman of African American descent to have won the award.','/upload/images/channels/artists/1577961488499_x7boe_HalleBerry_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(24,'va9wdk4wkvontc','Jay Z','Shawn Corey Carter, known professionally as Jay-Z, is an American rapper, songwriter, producer, entrepreneur, and record executive. He is regarded as one of the greatest rappers of all time. ','/upload/images/channels/artists/1577961482042_wmg23n_JayZ_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(25,'va9wdk4wkw4cqc','Jennifer Aniston','Jennifer Joanna Aniston is an American actress, film producer, and businesswoman. The daughter of actors John Aniston and Nancy Dow, she began working as an actress at an early age with an uncredited role in the 1987 film Mac and Me. Her first major film role came in the 1993 horror comedy Leprechaun.','/upload/images/channels/artists/1577961475013_ldq7a_JenniferAniston_main.jpeg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(26,'va9wdk4wkwk45c','Jennifer Lopez','Jennifer Lynn Lopez, also known by her nickname J.Lo, is an American actress, singer, dancer, fashion designer, producer and businesswoman. In 1991, Lopez began appearing as a Fly Girl dancer on In Living Color, where she remained a regular until she decided to pursue an acting career in 1993.','/upload/images/channels/artists/1577961468900_4d59ls_JenniferLopez_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(27,'va9wdk4wl107rc','Justin Bieber','Justin Drew Bieber is a Canadian singer, songwriter and actor. Discovered at 13 years old by talent manager Scooter Braun after he had watched his YouTube cover song videos, Bieber was signed to RBMG Records in 2008.','/upload/images/channels/artists/1577960646986_mqkoje_image_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(28,'va9wdk4wlnzh3c','Taylor Swift','Taylor Alison Swift is an American singer-songwriter. She is known for narrative songs about her personal life, which have received widespread media coverage. At age 14, she became the youngest artist signed by the Sony/ATV Music publishing house and, at 15, she signed her first record deal.','/upload/images/channels/artists/1577961718224_8nm4sg_9108999_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(29,'va9wdk4wlop14c','Sandra Bullock','Sandra Annette Bullock is an American actress, producer, and philanthropist. She was the highest paid actress in the world in 2010 and 2014. In 2015, Bullock was chosen as Peoples Most Beautiful Woman and was included in Times 100 most influential people in the world in 2010.','/upload/images/channels/artists/1577961751157_k6aff_SandraBullock_main.jpg','channel',1,0,0,2,0,0,0,0,NULL,NULL,NULL),(30,'va9wdk4wlp6e4c','Rihanna','Robyn Rihanna Fenty is a Barbadian singer, songwriter, fashion designer, actress and businesswoman, who has been recognized for embracing various musical styles and reinventing her image throughout her career.','/upload/images/channels/artists/1577961775256_v6vkfe_Rihanna_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(31,'va9wdk4wlpnc4c','Nicki Minaj','Onika Tanya Maraj-Petty, known professionally as Nicki Minaj, is a Trinidad and Tobago-born rapper, singer, songwriter, actress, and model.','/upload/images/channels/artists/1577961797274_rs17q_NickiMinaj_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL),(32,'va9wdk4wlq2e1c','Shakira','Shakira Isabel Mebarak Ripoll is a Colombian singer, songwriter, dancer, businesswoman, and philanthropist. Born and raised in Barranquilla, she made her recording debut under Sony Music Colombia at the age of 13','/upload/images/channels/artists/1577961816748_vb81r_Shakira_main.jpg','channel',1,0,0,0,0,0,0,0,NULL,NULL,NULL);
/*!40000 ALTER TABLE `artists` ENABLE KEYS */;
