INSERT INTO `blogs` VALUES (2,'PNB  - Interest Rates - Deposit','<div class=\"WordSection1\" style=\"/* background: #ffffff; */padding: 30px 20px 20px 20px; border: 1px solid #ccc; border-radius: 4px;\">\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\"><strong><span style=\"font-size: 14.0pt; font-family: \'open_sansbold\',\'serif\'; color: #b1113e;\">Domestic &amp; NRI Saving Account Interest Rates : (W.E.F. 1st July 2021)</span></strong></p>\n<table class=\"MsoNormalTable\" style=\"width: 100.0%; border-collapse: collapse; overflow-x: auto;\" border=\"0\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\n<tbody>\n<tr>\n<td style=\"border: solid #CCCCCC 1.0pt; background: #FFECB6; padding: 5.25pt 5.25pt 5.25pt 5.25pt;\">\n<p class=\"MsoNormal\">&nbsp;</p>\n</td>\n<td style=\"border: solid #CCCCCC 1.0pt; border-left: none; background: #FFECB6; padding: 5.25pt 5.25pt 5.25pt 5.25pt;\">\n<p><strong><span style=\"color: black;\">Rate Of Interest</span></strong></p>\n</td>\n</tr>\n<tr>\n<td style=\"border: solid #CCCCCC 1.0pt; border-top: none; padding: 3.75pt 7.5pt 3.75pt 7.5pt;\">\n<p>Savings Fund Account Balance below Rs. 100 Crore</p>\n</td>\n<td style=\"border-top: none; border-left: none; border-bottom: solid #CCCCCC 1.0pt; border-right: solid #CCCCCC 1.0pt; padding: 3.75pt 7.5pt 3.75pt 7.5pt;\">\n<p>3.00% p.a.</p>\n</td>\n</tr>\n<tr>\n<td style=\"border: solid #CCCCCC 1.0pt; border-top: none; padding: 3.75pt 7.5pt 3.75pt 7.5pt;\">\n<p>Savings Fund Account Balance of Rs. 100 Crore &amp; above</p>\n</td>\n<td style=\"border-top: none; border-left: none; border-bottom: solid #CCCCCC 1.0pt; border-right: solid #CCCCCC 1.0pt; padding: 3.75pt 7.5pt 3.75pt 7.5pt;\">\n<p>3.00% p.a.</p>\n</td>\n</tr>\n</tbody>\n</table>\n<p style=\"margin-bottom: .0001pt; text-align: justify; line-height: 15.0pt; vertical-align: top;\"><span style=\"font-size: 12.0pt; font-family: \'open_sansregular\',\'serif\';\">For Bulk deposit, please contact your near