#cccccc; border-bottom: 1pt solid #cccccc; border-left: 1pt solid #cccccc; border-image: initial; border-top: none; padding: 3.75pt 7.5pt; width: 38.1308%;\" colspan=\"2\">\n<p><strong><span style=\"font-size: 12.0pt; font-family: \'open_sansregular\',\'serif\';\">Medium and Long Term Government Deposit (MLTGD</span></strong><span style=\"font-size: 12.0pt; font-family: \'open_sansregular\',\'serif\';\">)</span></p>\n</td>\n</tr>\n<tr>\n<td style=\"border-right: 1pt solid #cccccc; border-bottom: 1pt solid #cccccc; border-left: 1pt solid #cccccc; border-image: initial; border-top: none; padding: 3.75pt 7.5pt; width: 23.7383%;\">\n<p><span style=\"font-size: 12.0pt; font-family: \'open_sansregular\',\'serif\';\">Medium Term Government Deposit</span></p>\n</td>\n<td style=\"border-top: none; border-left: none; border-bottom: 1pt solid #cccccc; border-right: 1pt solid #cccccc; padding: 3.75pt 7.5pt; width: 14.3925%;\">\n<p><span style=\"font-size: 12.0pt; font-family: \'open_sansregular\',\'serif\';\">2.25%</span></p>\n</td>\n</tr>\n<tr>\n<td style=\"border-right: 1pt solid #cccccc; border-bottom: 1pt solid #cccccc; border-left: 1pt solid #cccccc; border-image: initial; border-top: none; padding: 3.75pt 7.5pt; width: 23.7383%;\">\n<p><span style=\"font-size: 12.0pt; font-family: \'open_sansregular\',\'serif\';\">Long Term Government Deposit</span></p>\n</td>\n<td style=\"border-top: none; border-left: none; border-bottom: 1pt solid #cccccc; border-right: 1pt solid #cccccc; padding: 3.75pt 7.5pt; width: 14.3925%;\">\n<p><span style=\"font-size: 12.0pt; font-family: \'open_sansregular\',\'serif\';\">2.50%</span></p>\n</td>\n</tr>\n</tbody>\n</table>\n<p class=\"MsoNormal\"><span style=\"font-size: 14.0pt; line-height: 115%;\">&nbsp;</span></p>\n</div>','b90lkrhq87z3',2,81,0,0,'/upload/images/blogs/1627308219870_m__main.png',1,1892,3,0,0,0,NULL,0,0,0,0,0,NULL,NULL,1,0,1,1,'2021-07-27 14:51:20','everyone','2021-07-24 12:06:23','2021-07-27 14:51:20'),(4,'PNB - Easily Green PIN for Debit Card','<div class=\"WordSection1\">\n<p style=\"padding: 10px 0; margin-bottom: .0001pt; text-align: center; line-height: normal; background: #A20A3A; vertical-align: top;\"><span style=\"font-size: 12pt;\"><strong><span style=\"font-family: open_sansregular, serif; color: #fbbc09;\">Green PIN - Debit Card</span></strong></span></p>\n<br />\n<p style=\"display: inline-block; float: right; clear: right; padding: 10px 0; margin-bottom: 7.5pt; line-height: normal; vertical-align: top;\"><span style=\"font-size: 12pt;\"><a href=\"https://netbanking.netpnb.com/corp/AuthenticationController?FORMSGROUP_ID__=AuthenticationFG&amp;__START_TRAN_FLAG__=Y&amp;__FG_BUTTONS__=LOAD&amp;ACTION.LOAD=Y&amp;AuthenticationFG.LOGIN_FLAG=1&amp;BANK_ID=024\" target=\"_blank\" rel=\"noopener\"> <strong><span style=\"text-decoration: none; cursor: pointer; padding: 10px; color: white; background: #4caf50;\">Generate Debit Card PIN</span></strong> </a></span></p>\n<br /><br />\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\"><span style=\"font-size: 12pt;\"><strong><span style=\"font-family: open_sansregular, serif; color: #b1113e;\">Procedure For Setting Debit Card PIN At PNB ATMs/IBS Account Using OTP - Automaticaly Sent At The Time Of Issue Of New Cards (Vallidity 72 Hours) Delivered On Registered Mobile Number</span></strong></span></p>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\">&nbsp;</p>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\"><span style=\"font-size: 12pt;\"><strong><span style=\"font-family: open_sansregular, serif;\">Self - Generation Of OTP For Setting Duplicate Debit Card PIN:</span></strong></span></p>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\">&nbsp;</p>\n<ul>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Please send SMS&nbsp;<strong>DCPIN space CARDNUMBER</strong>&nbsp;to 5607040 from registered mobile number for active debit card.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Immediately on successful validation of your card/mobile credentials, system will send&nbsp;<strong><span style=\"font-family: open_sansregular, serif; color: brown;\">6 digits OTP&nbsp;</span></strong><span style=\"font-family: open_sansregular, serif;\">on registered mobile number with validity of 72 hours. </span></li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Using this OTP, you can set debit card PIN of your choice through any PNB ATM/IBS account as mentioned below.</li>\n</ul>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\"><span style=\"font-size: 12pt;\"><strong><span style=\"font-family: open_sansregular, serif;\">Setting Of Debit Card PIN Through PNB ATM Using OTP</span></strong></span></p>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\">&nbsp;</p>\n<ul>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Please swipe your debit card at any PNB ATM machine.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Under Banking on language selection screen, GREEN PIN option has been provided for setting the debit card PIN using OTP.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Select GREEN PIN option, ATM screen will prompt to enter 6 digits OTP delivered on registered mobile number.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Enter 6 digit OTP and press OK.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">ATM screen will prompt you to enter 4 digits number of your choice as PIN of debit card and press OK.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Please re-enter the same 4 digits number again for confirmation of PIN.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">If entry of 4 digits number matches in both cases, system will store this as PIN and you will get the confirmation message on ATM screen.</li>\n</ul>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\"><span style=\"font-size: 12pt;\"><strong><span style=\"font-family: open_sansregular, serif; color: #b1113e;\">\"Thank you, your PIN has been set successfully. Please do not share it with anyone.\"</span></strong></span></p>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\">&nbsp;</p>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\"><span style=\"font-size: 12pt;\"><strong><span style=\"font-family: open_sansregular, serif;\">Setting Of Debit Card PIN Through IBS Account Using OTP:</span></strong></span></p>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\">&nbsp;</p>\n<ul>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Please login Into your IBS retail account.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Post login, click on Value Added Services ? Card Related Services 4?Set/Reset DebilCard PIN.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Select the account number to which card is attached and press Continue</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">System will prompt for Card Number Expiry Date(i.e. Month &amp; Year) and 6 digits OTP delivered on your registered mobile number</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Enter above information and click&nbsp;<strong>Submit</strong></li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">After-successful validation of your credentials, IBS screen will prompt you to enter and re-enter 4 digits number of your choice as PIN of debit card.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">If entry of 4 digits number matches in both cases, system will store this as PIN and you will get the confirmation message on IBS Screen</li>\n</ul>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\"><span style=\"font-size: 12pt;\"><strong><span style=\"font-family: open_sansregular, serif; color: #b1113e;\">\"Thank you, your PIN has been set successfully. Please do not share it with anyone\".</span></strong></span></p>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\">&nbsp;</p>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\"><span style=\"font-size: 12pt;\"><strong><span style=\"font-family: open_sansregular, serif;\">Setting Of Debit Card PIN Through PNB One Using OTP:</span></strong></span></p>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\">&nbsp;</p>\n<ul>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Please login into your PNB One App.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Post login, click on the Debit Card button, then in the next page click on Generate Green PIN.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">In the next page, from the drop-down, select the account number to which card is attached and press Continue.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">System will prompt for Card Number Expiry Date (i.e. Month &amp; Year) and 6 digits OTP delivered on your registered mobile number.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">Enter above information and click Continue.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">After-successful validation of your credentials, the next screen will prompt you to enter and re-enter 4 digits number of your choice as PIN of debit card.</li>\n<li style=\"padding-left: 10px; list-style-image: url(\'data:image/png;base64,\');\">If entry of 4 digits number matches in both cases, system will store this as PIN and you will get the confirmation message on App Screen.</li>\n</ul>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\"><span style=\"font-size: 12pt;\"><strong><span style=\"font-family: open_sansregular, serif; color: #b1113e;\">\"Thank you, your PIN has been set successfully. Please do not share it with anyone.\"</span></strong></span></p>\n<p style=\"margin-bottom: .0001pt; line-height: normal; vertical-align: top;\">&nbsp;</p>\n<p style=\"line-height: normal; vertical-align: top;\"><span style=\"font-size: 12pt;\"><strong><span style=\"font-family: open_sansregular, serif; color: #b1113e;\"><a href=\"https://www.pnbindia.in/downloadprocess.aspx?fid=TIIgUtQX0pD58kQBkr8sTg==\">Click here to know more about Green PIN</a></span></strong></span></p>\n<p style=\"line-height: normal; vertical-align: top;\">&nbsp;</p>\n<p class=\"MsoNormal\"><span lang=\"EN-US\" style=\"font-size: 12pt;\">&nbsp;</span></p>\n</div>','bj5gkrna4vgn',2,81,0,0,'/upload/images/blogs/1627464150391___main.PNG',1,2301,0,0,0,0,NULL,0,0,0,0,0,NULL,NULL,1,0,1,1,'2021-07-29 09:37:40','everyone','2021-07-28 09:22:30','2021-07-29 09:37:40'),(5,'Interest Rates on Savings Bank Deposits','<div>\r\n<div>\r\n<h2><img src=\"https://www.sbi.co.in/o/SBI-Theme/images/custom/icons/savings-bank-acc.png\" width=\"34\" height=\"35\" /> <strong>Savings Bank Deposits</strong></h2>\r\n</div>\r\n</div>\r\n<div>\r\n<div>\r\n<div>\r\n<h3>Interest Rates on Savings Bank Deposits</h3>\r\n<p>Applicable Interest Rates on Savings Bank Deposits w.e.f 15<sup>th</sup>&nbsp;October 2022</p>\r\n<br />\r\n<div class=\"table-responsive\">\r\n<table class=\"table table-borderd\" style=\"border-collapse: collapse; width: 72.6265%; height: 153.531px; border-color: #ced4d9; border-style: solid;\" border=\"1PX\">\r\n<tbody>\r\n<tr style=\"height: 44.75px; background-color: #280071;\">\r\n<th style=\"height: 44.75px; border-color: transparent; width: 29.2182%;\"><span style=\"color: #ffffff;\">Savings Bank deposit slabs</span></th>\r\n<th style=\"height: 44.75px; border-color: transparent; width: 22.8023%;\"><span style=\"color: #ffffff;\">Existing Rate of Interest</span></th>\r\n<th style=\"height: 44.75px; border-color: transparent; width: 47.9456%;\"><span style=\"color: #ffffff;\">Revised Rate of Interest w.e.f. 15.10.2022</span></th>\r\n</tr>\r\n<tr style=\"height: 54.3906px;\">\r\n<td style=\"height: 54.3906px; width: 29.2182%;\">\r\n<p>Balances less than&nbsp;Rs. 10 Crore</p>\r\n</td>\r\n<td style=\"height: 108.781px; text-align: center; width: 22.8023%;\" colspan=\"1\" rowspan=\"2\">2.70% p.a</td>\r\n<td style=\"height: 54.3906px; width: 47.9456%;\"><strong>2.70% p.a.</strong></td>\r\n</tr>\r\n<tr style=\"height: 54.3906px;\">\r\n<td style=\"height: 54.3906px; width: 29.2182%;\">Balances Rs. 10 Crore &amp; Above</td>\r\n<td style=\"height: 54.3906px; width: 47.9456%;\">\r\n<p><strong>3.00% p.a.</strong></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<div class=\"faqaccordion_0 global_acc\">&nbsp;</div>\r\n</div>\r\n</div>\r\n<p class=\"pull-right\"><em>Last Updated On : Tuesday, 18-10-2022</em></p>\r\n</div>','b1wbfbln5rvnuz',4,81,0,0,'/upload/images/blogs/1696063145458_s__main.png',1,1768,0,0,0,0,NULL,0,0,0,0,0,NULL,NULL,1,0,1,1,'2023-09-30 08:39:06','everyone','2023-09-30 08:29:57','2023-09-30 08:39:06');
